// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        Recipient r = new Recipient();
        vm.deal(address(r), amount);
        r.attack(c, amount);
        // General rule: for any actor and any admissible credited amount,
        // the second consecutive withdrawal delivers exactly 0 Ether.
        assertTrue(r.delivered(1) == 0);
    }
}

contract Recipient {
    uint256[2] private got;
    bool private ok2;

    function attack(Reentrance c, uint256 amount) external {
        c.addToBalance{value: amount}();
        c.withdrawBalance();
        // second withdrawal: record what arrives, or note failure
        try c.withdrawBalance() { ok2 = true; } catch { ok2 = false; }
    }

    function delivered(uint256 i) external view returns (uint256) {
        if (i == 1) {
            if (!ok2) return type(uint256).max; // second call failed entirely
            return got[1];
        }
        return got[0];
    }

    receive() external payable {
        if (got[0] == 0 && got[1] == 0 && got[0] == 0) {
            got[0] = got[1];
        }
        // shift: first receipt fills slot0, later receipts fill slot1
        if (got[0] != 0 || shifted) {
            got[1] = msg.value;
        } else {
            got[0] = msg.value;
            shifted = true;
        }
    }

    bool private shifted;
}
